/// at 89 commands; oversized input fails closed, never tuned per font.
pub const MAX_COMMANDS: usize = 512;

/// Supplied fixed affine correspondence to outline controls (Hobby (31)).
#[derive(Clone, Debug)]
pub struct Sample {
    pub terms: Vec<(usize, f64)>,
}

impl Sample {
    pub fn vertex(index: usize) -> Self {
        Sample {
            terms: vec![(index, 1.0)],
        }
    }

    pub fn affine(i0: usize, t0: f64, i1: usize, t1: f64) -> Self {
        Sample {
            terms: vec![(i0, t0), (i1, t1)],
        }
    }

    fn point(&self, points: &[[f64; 2]]) -> [f64; 2] {
        let mut p = [0.0, 0.0];
        for &(index, weight) in &self.terms {
            p[0] += weight * points[index][0];
            p[1] += weight * points[index][1];
        }
        p
    }
}

fn basis_row(weights: &[(usize, f64)], n: usize) -> Vec<f64> {
    let mut row = vec![0.0; n];
    for &(i, w) in weights {
        row[i] += w;
    }
    row
