//! Shared Hobby least-squares row construction.
//!
//! Source: Hobby (1)-(3) edge rows and (4)-(5) pair-width residual, with
//! directions, lengths and validity checks from the input geometry; see the
//! project audit of the 1993 report. Both row-system owners delegate here so
//! the stored equations have one implementation; solver-specific row labels
//! stay with the callers.

use super::{basis_row, Sample};

/// Outer product of the correspondence basis with a direction, raveled
/// per-coordinate `(x0, y0, x1, y1, ...)`.
pub(super) fn projected(
    point_count: usize,
    a: &Sample,
    dir: [f64; 2],
    b: Option<&Sample>,
) -> Vec<f64> {
    let ba = basis_row(&a.terms, point_count);
    let mut row = vec![0.0; 2 * point_count];
    for (k, w) in ba.iter().enumerate() {
        // Plain assignment keeps the IEEE 754 product sign; `+=` would fold
        // exact `-0.0` entries to `+0.0`.
        row[2 * k] = w * dir[0];
        row[2 * k + 1] = w * dir[1];
    }
    if let Some(other) = b {
        let bb = basis_row(&other.terms, point_count);
        for (k, w) in bb.iter().enumerate() {
            row[2 * k] -= w * dir[0];
            row[2 * k + 1] -= w * dir[1];
        }
    }
    row
}

/// Hobby (1)-(3) edge rows in sum, difference, stretch, bend order.
pub(super) struct EdgeRows {
    pub(super) sum: Vec<f64>,
    pub(super) diff: Vec<f64>,
    pub(super) stretch: Vec<f64>,
    pub(super) bend: Vec<f64>,
}

/// Hobby (1)-(3), with directions/lengths from input geometry.
pub(super) fn edge_rows(
    points: &[[f64; 2]],
    height: f64,
    i: usize,
    j: usize,
) -> Result<EdgeRows, ()> {
    let a = Sample::vertex(i);
    let b = Sample::vertex(j);
    let pa = a.point(points);
    let pb = b.point(points);
    let delta = [pb[0] - pa[0], pb[1] - pa[1]];
    let length = delta[0].hypot(delta[1]);
    if !(length > 0.0) {
        return Err(());
    }
    let tangent = [delta[0] / length, delta[1] / length];
    let normal = [-tangent[1], tangent[0]];
    let alpha1 = 1000.0 / height.powi(3);
    let ri = projected(points.len(), &a, normal, None);
    let rj = projected(points.len(), &b, normal, None);
    let sum: Vec<f64> = ri
        .iter()
        .zip(rj.iter())
        .map(|(x, y)| (x + y) * (alpha1 * length / 4.0).sqrt())
        .collect();
    let diff: Vec<f64> = rj
        .iter()
        .zip(ri.iter())
        .map(|(x, y)| (x - y) * (alpha1 * length / 12.0).sqrt())
        .collect();
    let scale = (25.0 * length / height).sqrt() / length;
    let stretch: Vec<f64> = projected(points.len(), &b, tangent, Some(&a))
        .iter()
        .map(|x| x * scale)
        .collect();
    let bend: Vec<f64> = rj
        .iter()
        .zip(ri.iter())
        .map(|(x, y)| (x - y) * scale)
        .collect();
    Ok(EdgeRows {
        sum,
        diff,
        stretch,
        bend,
    })
}

/// Hobby (4),(5): input contacts, medial point and arc-length weight.
pub(super) fn pair_residual(
    points: &[[f64; 2]],
    a: &Sample,
    b: &Sample,
    arc: f64,
    medial: [f64; 2],
) -> Result<(Vec<f64>, f64, [f64; 2]), ()> {
    if !(arc.is_finite() && arc > 0.0) {
        return Err(());
    }
    let pa = a.point(points);
    let pb = b.point(points);
    let chord = [pa[0] - pb[0], pa[1] - pb[1]];
    let distance = chord[0].hypot(chord[1]);
    if !(distance > 0.0) {
        return Err(());
    }
    let width = 2.0 * (pa[0] - medial[0]).hypot(pa[1] - medial[1]);
    let other = 2.0 * (pb[0] - medial[0]).hypot(pb[1] - medial[1]);
    if !(width > 0.0) || (width - other).abs() > 1e-12 + 1e-10 * other.abs() {
        return Err(());
    }
    let normal = [chord[0] / distance, chord[1] / distance];
    let tangent = [-normal[1], normal[0]];
    let mut error = projected(points.len(), a, normal, Some(b));
    for x in error.iter_mut() {
        *x /= -width;
    }
    Ok((error, width, tangent))
}
