    69	/// Hobby (4),(5): input contacts, medial point and arc-length weight.
    70	pub(super) fn pair_residual(
    71	    points: &[[f64; 2]],
    72	    a: &Sample,
    73	    b: &Sample,
    74	    arc: f64,
    75	    medial: [f64; 2],
