1|//! Shared Hobby least-squares row construction.
2|//!
3|//! Source: Hobby (1)-(3) edge rows and (4)-(5) pair-width residual, with
4|//! directions, lengths and validity checks from the input geometry. Both
5|//! row-system owners delegate here; each caller supplies its own
6|//! correspondence projection, so guard semantics, arithmetic order and row
7|//! order are unchanged.
8|
9|use super::Sample;
10|
11|/// Hobby (1)-(3) edge rows in sum, difference, stretch, bend order.
12|pub(super) struct EdgeRows {
13|    pub(super) sum: Vec<f64>,
14|    pub(super) diff: Vec<f64>,
15|    pub(super) stretch: Vec<f64>,
16|    pub(super) bend: Vec<f64>,
17|}
18|
19|/// Hobby (1)-(3), with directions/lengths from input geometry.
20|pub(super) fn edge_rows(
21|    points: &[[f64; 2]],
22|    height: f64,
23|    i: usize,
24|    j: usize,
25|    project: impl Fn(&Sample, [f64; 2], Option<&Sample>) -> Vec<f64>,
26|) -> Result<EdgeRows, ()> {
27|    let a = Sample::vertex(i);
28|    let b = Sample::vertex(j);
29|    let pa = a.point(points);
30|    let pb = b.point(points);
31|    let delta = [pb[0] - pa[0], pb[1] - pa[1]];
32|    let length = delta[0].hypot(delta[1]);
33|    if !(length > 0.0) {
34|        return Err(());
35|    }
36|    let tangent = [delta[0] / length, delta[1] / length];
37|    let normal = [-tangent[1], tangent[0]];
38|    let alpha1 = 1000.0 / height.powi(3);
39|    let ri = project(&a, normal, None);
40|    let rj = project(&b, normal, None);
41|    let sum: Vec<f64> = ri
42|        .iter()
43|        .zip(rj.iter())
44|        .map(|(x, y)| (x + y) * (alpha1 * length / 4.0).sqrt())
45|        .collect();
46|    let diff: Vec<f64> = rj
47|        .iter()
48|        .zip(ri.iter())
49|        .map(|(x, y)| (x - y) * (alpha1 * length / 12.0).sqrt())
50|        .collect();
51|    let scale = (25.0 * length / height).sqrt() / length;
52|    let stretch: Vec<f64> = project(&b, tangent, Some(&a))
53| 
